export type RulesContentSection = { heading: string; body: string };
export type RulesContentFaq = { question: string; answer: string };

export const rulesLibraryContent: Record<string, {
  sections: RulesContentSection[];
  faqs: RulesContentFaq[];
}> = {
  "/rules/employee-pf": {
    sections: [
      { heading: "Check coverage before estimating a deduction", body: "A ceiling used to test mandatory coverage is not automatically the wage base for every existing member's contribution. Start with the member's joining history, establishment coverage, wage definition, and the date on which the payroll period falls. Ask payroll to identify the notification and scheme provision applied to the individual record. Do not convert a headline ceiling into a personal deduction by multiplying it by a contribution percentage without checking the facts. An employee who was already a member may follow different continuation rules from a person who was previously excluded." },
      { heading: "Read the September transition by wage month", body: "The EPFO FAQ opened for this page describes the revised ceiling and explains how the September 2026 change is handled across the effective date. Payroll records should show which wage days were governed by the earlier limit and which fell under the revised notification. If a later month contains a recovery or adjustment, request the wage-month calculation rather than comparing only the bank debit. Keep the employer's ECR acknowledgement, payslip, joining record, and written explanation together. The FAQ is a dated source; a later notification may alter the procedure or clarify edge cases." },
      { heading: "Separate EPF, EPS, and EDLI lines", body: "A provident-fund statement can contain several statutory components that are not interchangeable. Ask which portion represents the employee contribution, the employer share routed to the provident account, pension allocation, and insurance-related remittance. A CTC sheet may describe employer costs differently from the portal ledger, so reconcile both instead of assuming each figure is an additional cash benefit. Check the member passbook and the employer's month-level statement for posted amounts. If a component is absent or delayed, ask for a transaction reference and the relevant wage period before concluding that the entire contribution was missed." },
      { heading: "What to keep for a payroll query", body: "Record the establishment name, member identifier in a private place, wage month, gross salary components, eligible wage basis, contribution figures, and the date you contacted payroll. Share sensitive identifiers only through an authenticated channel that the employer or EPFO provides; do not paste them into an open feedback form. A useful query asks for the provision used, the effective notification date, and a component-wise explanation. Avoid sending an entire bank statement when a redacted payslip and portal extract can answer the question. Keep a copy of any correction because later annual statements may aggregate earlier adjustments." },
      { heading: "Illustrative scenario: one ceiling, two histories", body: "Illustrative scenario: two colleagues earn the same monthly amount, but one has an established EPF membership while the other is checking whether mandatory enrolment begins under a revised ceiling. They should not assume the same calculation follows from identical pay. The first checks continuation and contribution rules for an existing member; the second asks payroll how the effective date, eligible wages, and membership status are being applied. Neither person can resolve the question from a CTC headline alone. This example shows why employment history and wage-period dates belong beside the amount in a payroll reconciliation." },
      { heading: "Keep the estimate inside its boundary", body: "This reference explains one official ceiling notice; it does not decide whether a particular worker is covered, whether an exception applies, or how the full wage definition operates in a complex salary structure. It does not replace the EPF Scheme, EPS rules, EDLI provisions, amendments, or a member's account record. For a disputed contribution, compare the current notification with the wage ledger and ask the responsible authority for case-specific guidance. Do not use this page to promise a future pension, infer take-home pay, or forecast investment returns. Its practical purpose is to make the next payroll question more precise." },
      { heading: "Close the loop with a dated reconciliation", body: "Once payroll responds, compare the explanation with the next passbook update and note whether the correction was a fresh remittance or a reclassification. Check that the Universal Account Number has not been confused with an establishment code, and redact both when sending a general query. A discrepancy should be described by month and component rather than as a lifetime total. Keep the acknowledgement number, response date, and any supporting circular in the same folder. This trail helps distinguish a processing delay from a repeated calculation issue and gives a later reviewer an auditable sequence." }
    ],
    faqs: [
      { question: "Does the revised ceiling set my personal contribution?", answer: "Not by itself. Confirm membership history, eligible wages, the scheme rule, and the payroll period before using any percentage." },
      { question: "Which record should I check first?", answer: "Compare the wage-month payslip with the member passbook and ask payroll for the calculation basis and any adjustment reference." }
    ]
  },
  "/rules/gratuity-wages": {
    sections: [
      { heading: "Identify the employment category first", body: "The formula is only one part of a gratuity question. Record whether the employment was permanent, fixed term, or another arrangement, then collect the appointment letter, amendments, service dates, and separation document. A label used by a recruiter does not settle legal status. The Ministry's dated FAQ gives a particular explanation for fixed-term expiry, while other situations can turn on continuity, establishment coverage, wage components, and the reason employment ended. If the facts do not fit the page's limited description, stop before turning a monthly salary estimate into an entitlement claim." },
      { heading: "Build a wage record, not a CTC guess", body: "Write down each recurring and one-time component separately: basic pay, dearness allowance where applicable, variable incentives, reimbursements, employer retirement contributions, and benefits in kind. Then ask which items the governing definition includes or excludes for the relevant period. CTC commonly combines employer costs and conditional payments, so it cannot be copied into a wage field without analysis. Keep the payroll explanation, payslips, employment agreement, and any revised compensation letter. A transparent component list helps a professional adviser identify the disputed item instead of debating a single large total whose construction is unclear." },
      { heading: "Reconcile service dates against records", body: "Use the date employment began, periods of interruption, transfer or rehire events, and the final date recognized by the employer. Compare those dates across appointment records, attendance, provident-fund history, and the separation letter. A difference of weeks can matter to a threshold calculation, but this page does not adjudicate whether a period legally counts. Ask HR to state the service span it used and show how it treated leave, notice, suspension, or a change of entity. If the employer's timeline conflicts with your documents, preserve the disagreement in writing and seek advice before accepting the estimate as final." },
      { heading: "Separate the formula from eligibility", body: "A familiar daily-wage multiplier does not prove that a payment is due in an individual case. Eligibility can depend on the applicable statute, category of worker, covered establishment, qualifying service, separation event, and the version of law in force. The amount also depends on the statutory wage base and any operative ceiling. This library entry identifies what the opened Ministry sources say; it does not determine every exception, transition, forfeiture issue, tax treatment, or recovery. Treat the result as a prompt to verify inputs and ask for an itemized employer calculation, not as a demand letter." },
      { heading: "Illustrative scenario: payroll uses a broad package number", body: "Illustrative scenario: a departing employee sees a gratuity estimate based on the annual CTC divided into twelve months. The employee asks payroll to list the wage components used, confirm the recognized service period, and name the legal provision behind the calculation. The response shows that employer contributions and a conditional bonus were included in the package total. The employee does not assume those items belong in the statutory wage base; they compare the answer with the dated Ministry FAQ and obtain advice for the specific contract. The example demonstrates a verification sequence, not a universal result." },
      { heading: "Know when the source is not enough", body: "A Ministry FAQ is a useful explanation but may not answer a disputed case or reflect a later notification. Check the publication date on both the FAQ and the underlying Code, and look for a subsequent amendment before relying on a ceiling or service rule. If you are handling death, disability, seasonal work, piece-rate pay, a transfer between employers, or contested service continuity, the monthly illustration here may not fit. Ask the employer for its written reasoning and consult a qualified labour adviser or the responsible authority when money or a limitation period is at stake." },
      { heading: "Make an employer calculation reproducible", body: "Ask for the arithmetic in writing: last drawn eligible wage, counted service, completed formula years, statutory cap if relevant, and any amount already paid. Request the date on which each input was measured; a promotion letter issued after the final working day may not change the base used in a particular computation. If the company uses a different formula for a more generous contractual benefit, ask it to label that enhancement separately from the statutory amount. A reproducible sheet lets you correct a date or component without debating the entire settlement as one unexplained figure." }
    ],
    faqs: [
      { question: "Can I multiply CTC by the gratuity formula?", answer: "No. First identify the statutory wage base and employment category from current documents and rules." },
      { question: "Does an estimate prove eligibility?", answer: "No. Eligibility, service continuity, and the separation event require fact-specific review." }
    ]
  },
  "/rules/leave-encashment": {
    sections: [
      { heading: "Start with the leave ledger", body: "Download or request the balance as of a named date, with separate lines for earned, casual, sick, compensatory, and other leave categories. Check opening balance, accruals, usage, lapses, carry-forward, and any manual adjustment. A single portal total may conceal different rules for different leave types. Compare the record with applications, approval emails, attendance, and payslips. If the displayed balance changed after resignation or transfer, ask which policy version and cutoff date were used. Keep screenshots or a dated export before access to the employer system ends, while respecting the employer's data rules." },
      { heading: "Distinguish a policy benefit from a statutory right", body: "The Ministry's Additional FAQs discuss leave under the Occupational Safety, Health and Working Conditions Code and acknowledge that a more favourable applicable state-law benefit may matter. That wording is not permission to assume the same entitlement for every role. Establish whether your work and establishment fit the relevant legal category, whether another state enactment governs, and whether the employer policy grants a better term. Ask HR to cite the policy and legal basis separately. When two documents appear inconsistent, record the versions and ask for a written explanation rather than choosing the line that produces the larger number." },
      { heading: "Ask how the payable amount is built", body: "A leave balance and a cash value are different records. Request the salary component used, the divisor, the number of encashable days, and the date at which the rate is frozen. Confirm whether the employer treats weekends, holidays, partial days, or carry-forward differently. This page does not supply a universal rupee formula because the inputs can depend on the governing rule and policy. If the final settlement offsets a leave amount against notice recovery, ask for both calculations as separate lines. A clear reconciliation prevents an apparent net total from hiding a disputed leave balance." },
      { heading: "Preserve the application trail", body: "Where leave was requested but not approved, retain the date submitted, the requested period, the manager's response, and any operational reason given. The Ministry FAQ distinguishes applications that were not granted from unused leave in its explanation of carry-forward and encashment. Do not rewrite a request after the fact or infer approval from a calendar entry. If a manager gave verbal direction, send a neutral confirmation through the ordinary workplace channel. A contemporaneous record helps explain why days remain unused and gives payroll a factual basis to reconcile the ledger." },
      { heading: "Illustrative scenario: a balance changes at exit", body: "Illustrative scenario: an employee's leave portal shows one balance before notice and a smaller one in the draft final statement. The employee requests the ledger's opening amount, each leave day booked during notice, the category that was encashed, and the policy cutoff used. Payroll finds a late attendance import and corrects the balance. The employee checks the revised statement against the application history before agreeing to the total. The point is not that every reduction is an error; it is that each adjustment should have a date, category, and explanation that can be checked." },
      { heading: "Avoid applying this summary outside its scope", body: "The source is a dated labour-code FAQ, not an individual ruling and not a substitute for state rules, contract language, sector-specific exemptions, or a current employer policy. It does not decide whether a person is a worker under the Code, whether a particular category of leave is encashable, or how wage components are valued. If the employer operates across states, use the work location and applicable establishment details rather than headquarters alone. Raise a precise question with payroll or a qualified adviser and keep the answer beside the leave record that it explains." },
      { heading: "Request an itemized exit statement", body: "A useful final-settlement query names the leave year, category, balance date, accrual rule, carry-forward limit, days used, and days paid. Ask payroll to identify any adjustment created by an attendance import or approval entered after the cutoff. Preserve the leave policy version that was active during the relevant period, not merely the latest intranet page. If a balance was transferred during an internal move, ask which employer entity owns the historical liability. These details turn a disagreement about a number into specific questions that can be answered against records." }
    ],
    faqs: [
      { question: "Should I rely on the balance shown today?", answer: "Save a dated ledger and compare it with applications, accruals, and the policy cutoff used for exit." },
      { question: "Is every leave category cashable?", answer: "This page does not say that. Confirm the category, applicable law, and employer policy." }
    ]
  },
  "/rules/income-tax-new-regime": {
    sections: [
      { heading: "Scope: assessment year 2026–27", body: "This page summarizes the individual new-regime rate schedule published for Assessment Year 2026–27, which covers income earned up to March 2026. Tax year 2026–27 is the next period: income earned from April 2026 under the Income-tax Act, 2025. The Finance Bill 2026 memorandum said no change was proposed in the rates for that tax year; check the enacted position before using this table for it. It is not a rate forecast for a later assessment year and does not assume that every person is eligible for the same deductions, rebate, or tax treatment. Match the assessment year to the income period printed on the official return guidance. The Department's rate page and the Finance Act source are linked below. If the law or official portal changes after the verification date, use the newer primary source and do not carry this table forward by habit." },
      { heading: "Apply slabs progressively", body: "A slab schedule is marginal: each rate applies to the slice of taxable income inside that band, not to the entire amount once a threshold is crossed. Calculate taxable income first, then allocate each portion to the matching band. The rate rows are not a take-home-pay table; they exclude the effect of eligible deductions, rebate, surcharge, cess, tax credits, withholding, and special-rate income. Keep the amount and assessment year beside the calculation. A calculator that multiplies total income by the highest applicable percentage will overstate the basic slab tax." },
      { heading: "Treat rebate as a separate step", body: "For AY 2026–27, the Department says the maximum new-regime Section 87A rebate is ₹60,000 for an eligible resident individual with total income up to ₹12 lakh. Special-rate income such as specified capital gains is excluded from the rebate calculation, and marginal relief can matter just above the threshold. Rebate is relief after tax computation, not a salary deduction or another slab. Check the exact section and official computation for the year before making a payroll decision. Do not assume that the same rebate exists in the other regime." },
      { heading: "Build from taxable income carefully", body: "Begin with salary, taxable allowances, perquisites, and other income that belong in the relevant computation, then subtract only deductions and exemptions allowed by the chosen regime. Do not subtract a rent payment, investment, or employer contribution merely because it appears in a package statement. Keep the salary certificate (Form 16, or Form 130 from tax year 2026–27), payslips, bank interest records, and supporting documents for each field. The official return schedule controls the final classification. If you have capital gains, business income, non-resident status, or special-rate receipts, this simple slab explanation is incomplete and should not be forced to fit your case." },
      { heading: "Illustrative scenario: threshold does not change all income", body: "Illustrative scenario: a resident employee's taxable income moves from one band into the next after a variable payment. The employee calculates the lower-band portions first, then applies the next marginal rate only to the additional slice. They check whether the rebate threshold still applies, review any marginal-relief calculation in the official schedule, and keep AY 2026–27 on the worksheet. They do not conclude that the entire income is suddenly taxed at the new marginal percentage. This example illustrates progressive arithmetic without predicting a specific person's final liability." },
      { heading: "Reconcile tax with payroll", body: "Payroll withholding is an estimate collected during the year, not proof that the final return has been correctly classified. Compare projected annual salary with the taxable salary reported in the salary certificate (Form 16, or Form 130 from tax year 2026–27), then include eligible non-salary income and credits where applicable. Ask payroll how it treated a joining bonus, stock benefit, reimbursement, or employer retirement contribution. A difference can reflect timing, valuation, declarations, or a changed law rather than a calculation defect. The Department's official e-filing resources and current Act should be used for filing decisions; this page cannot submit or validate a return." },
      { heading: "Check the rebate edge, not only the slab chart", body: "For this assessment year, the official new-regime summary pairs the ₹12 lakh total-income limit with a maximum rebate of ₹60,000, subject to eligibility and the special-rate exclusion. A person just above the limit should review marginal relief using the applicable return computation rather than assume the entire rebate disappears in a simple step. Keep tax on ordinary slabs separate from tax on capital gains or other special-rate income. Compare the computed liability before and after relief and note the source version, because a later Finance Act can change both the threshold and the way the relief is calculated." },
      { heading: "Record assumptions that affect eligibility", body: "Write the taxpayer's residential status, age category, income heads, assessment year, selected regime, and any special-rate receipt beside the estimate. These are not decorative labels: each can change which table or relief applies. A salary-only projection should state that it excludes interest, dividends, capital gains, and prior-employer income if those figures are not entered. Keep a separate line for tax already withheld so the remaining balance is not mistaken for the year's total liability. When the official portal offers a calculator for the same assessment year, compare its inputs with your worksheet rather than copying only the final amount." }
    ],
    faqs: [
      { question: "Does crossing one band tax all income at that rate?", answer: "No. Slab rates apply progressively to the portion of taxable income in each band." },
      { question: "Can I reuse this table next year?", answer: "Only after checking the official rates and rules for the new assessment year." }
    ]
  },
  "/rules/income-tax-old-regime": {
    sections: [
      { heading: "Use the matching age category and year", body: "The old-regime rates on this page are scoped to the individual category specified in the official table for Assessment Year 2026–27, meaning income earned up to March 2026. Income earned from April 2026 belongs to tax year 2026–27 under the Income-tax Act, 2025, so confirm the official rates for that year separately. Age can change the basic exemption threshold, so do not apply the under-sixty schedule to a senior citizen without checking the relevant row. Match the assessment year to the income period and confirm residence status before using the table. The Department's tax-rate page and Finance Act material are linked as primary references. A rate summary may not include every special case that appears on a filed return." },
      { heading: "Work through the progressive bands", body: "Allocate taxable income in order, applying each percentage only to the amount within its band. The basic slab calculation is distinct from the standard deduction, eligible exemptions, Chapter VI-A deductions, rebate, surcharge, and cess. Keep those items as separate lines so a deduction is not accidentally counted twice. A taxable-income figure is not the same as gross salary or CTC. The return computation may include other income and adjustments not represented by a salary-only worksheet, so reconcile source documents before using a rate table to compare two regimes." },
      { heading: "Keep Section 87A and surcharge relief apart", body: "For the modeled old-regime resident individual, Section 87A rebate is available only when total income does not exceed ₹5 lakh; it is limited to income tax or ₹12,500, whichever is lower. The rebate does not receive surcharge marginal relief above that boundary. Surcharge relief addresses a different high-income calculation and must not be blended into the old-regime rebate. Consult the official Act and return validation rules for the selected assessment year, then calculate each relief in its correct order. If a tax tool combines them without showing the steps, ask which rule produced the result." },
      { heading: "Check whether a deduction is actually eligible", body: "Receipts alone do not establish that a deduction qualifies. Verify the taxpayer, payment date, eligible recipient, instrument, documentary evidence, cap, and regime restriction for each item. House rent, home-loan interest, insurance, education, and retirement contributions have different statutory conditions. The old regime can permit deductions that the alternative regime does not, but that does not make every claimed expense deductible. Keep one evidence folder and label each document with the section it may support. Use the official return guide to confirm the schedule rather than relying on a generic list circulated without a tax year." },
      { heading: "Illustrative scenario: compare before electing", body: "Illustrative scenario: an employee has rent receipts and investment evidence but also values simple withholding and has income from a fixed deposit. The employee computes the old-regime taxable amount only after checking which items qualify, then compares it with the new-regime result for the same year and income. The employee does not assume that a higher deduction total guarantees lower final tax, because rates and eligibility differ. They retain the underlying receipts and compare the return rules before making an election. This is a decision method, not a prediction of the employee's liability." },
      { heading: "Know when a salary-only view is insufficient", body: "The rate table does not cover every capital gain, business receipt, foreign income, loss set-off, deduction interaction, or residency question. It cannot decide whether an expenditure meets the law or whether a document is adequate evidence. If the return includes multiple heads of income or a disputed exemption, use the official e-filing tool and consult a qualified tax professional. Do not modify payroll declarations just to make this comparison's displayed totals match a desired outcome. Record the source version and date so a future calculation can be rebuilt using the same assumptions." },
      { heading: "Model the old-regime rebate separately", body: "For the general resident-individual example, Section 87A rebate is limited to tax or ₹12,500, whichever is lower, and is not available once total income exceeds ₹5 lakh. A senior citizen may have a different basic exemption threshold, but that does not automatically change the rebate boundary. The sequence matters: determine income, compute eligible tax, apply the qualifying rebate, and add cess according to the official order. Do not carry a marginal-relief rule from a surcharge calculation into the rebate. Keep the taxpayer category visible on any worksheet so the result cannot be mistaken for a universal rate." },
      { heading: "Make deduction evidence traceable", body: "Create a ledger with the claimed section, payer, beneficiary, transaction date, amount, permitted limit, proof location, and the regime in which it may be used. Match bank debits to receipts and verify that a premium or contribution belongs to the taxpayer claiming it. A declaration filed with an employer can influence withholding but is not final evidence that a return claim qualifies. Remove duplicate entries when a payment appears in both a salary declaration and a personal spreadsheet. Preserve rejected or corrected claims with a short explanation, because an audit trail should show why an attractive deduction was not used." }
    ],
    faqs: [
      { question: "Does an old-regime rebate receive surcharge marginal relief?", answer: "Do not assume so. The rebate boundary and surcharge relief are separate rules with different thresholds." },
      { question: "Can every rent or investment payment be deducted?", answer: "No. Eligibility depends on the statutory condition, selected regime, year, and supporting evidence." }
    ]
  },
  "/rules/salary-standard-deduction-cess": {
    sections: [
      { heading: "Put the standard deduction in the right place", body: "A standard deduction reduces the eligible salary amount when the selected assessment-year rules allow it; it is not an employer-paid cash component and it does not reduce every kind of income. Confirm the amount and eligibility from the official rate table and return guidance for the year. Keep it separate from rent, provident-fund contributions, and other claimed deductions. If the taxpayer has pension or multiple employers, check how the return treats the total rather than applying the allowance once to every salary certificate. The figure on this page is tied to its displayed year." },
      { heading: "Cess is calculated after the tax components", body: "Health and Education Cess is applied to the tax amount at the rate specified for the assessment year, after considering surcharge and applicable relief in the statutory order. It is not a percentage of gross salary or taxable income. Compute the slab tax first, apply eligible rebate and surcharge treatment, then follow the official calculation sequence. If a payroll worksheet shows one amount labelled cess but does not reveal its base, ask for the component calculation. Small ordering mistakes near thresholds can create a visible difference even when the underlying salary figure is correct." },
      { heading: "Keep regime comparisons symmetrical", body: "Compare both regimes using the same gross salary, other income, assessment year, residency assumptions, and source records. Then apply only the deductions and exemptions permitted in each regime. Avoid entering the standard deduction manually if the calculator already applies it automatically. Treat employer retirement contributions and perquisites according to their own rules rather than folding them into the standard deduction. Save the assumptions and the official source version with the output. A comparison is useful only when each side covers the same income period and does not count a component twice." },
      { heading: "Illustrative scenario: investigate a salary certificate difference", body: "Illustrative scenario: a worker's tax worksheet and salary certificate (Form 16 up to March 2026, Form 130 after that) show different taxable salary. The worker first checks the assessment year, salary reported, standard deduction used, and other employer income. They then compare taxable perquisites and previous-employer salary before checking cess. A mismatch may arise because the personal sheet omitted a taxable benefit or because a payroll declaration changed late in the year. The worker asks payroll for the computation rather than editing the deduction amount to force agreement. This example shows a reconciliation path, not a conclusion about which document is wrong." },
      { heading: "Keep income types separate", body: "Salary includes more than fixed monthly pay, but not every reimbursement or employer cost is treated identically. A taxable allowance, perquisite, pension, or payment in lieu of salary can have a separate classification and valuation. Interest, capital gains, and business receipts do not become salary because they appear on the same tax return. Build a list of sources and income heads before applying a deduction. The Income Tax Department's salary guide and the current year's Act provide the classification boundary; this reference is not an exhaustive tax-return instruction." },
      { heading: "Preserve the calculation trail", body: "Save the official page or notification, the verification date, the annual gross amount, deduction line, tax before and after relief, surcharge if any, cess, and withholding already paid. Write a note when you deliberately exclude a component and why. This makes a later review faster if law changes, an employer issues a corrected salary certificate, or a tax notice asks for supporting detail. Do not upload identity numbers, payslips, or tax documents to public analytics. For an actual filing, the official portal and a qualified tax adviser take priority over an educational page." },
      { heading: "Check the full calculation order", body: "First determine taxable income after the deduction that applies to the selected regime; next compute slab and any special-rate tax; then apply an eligible rebate, surcharge, marginal relief, and cess in the sequence prescribed for that year. Payroll software may round at intermediate stages, so compare unrounded inputs before concluding that a small difference is an error. A corrected salary certificate can also change withholding already collected without changing the statutory rate. Record the gross-to-taxable bridge and do not classify the standard deduction as a cash allowance or a tax credit." },
      { heading: "Tie every figure to its assessment year", body: "A tax year label on an employer portal may describe the financial year, while the government rate page may use the assessment year. Write both labels on a comparison and confirm that the official table covers the same income period. For salary, check the employer's annual statement and the return schedule rather than assuming a prior payroll configuration remains correct. If you receive pension or salary from two employers, review the combined amount and avoid duplicating the standard deduction. Store the relevant source page with its retrieval date so a later reviewer can distinguish a changed rule from a changed input." }
    ],
    faqs: [
      { question: "Is cess a percent of salary?", answer: "No. It is applied to the computed tax base in the sequence set by the applicable rules." },
      { question: "Should the standard deduction be entered twice?", answer: "No. Check whether the payroll form or comparison tool has already included it." }
    ]
  },
  "/rules/professional-tax-states": {
    sections: [
      { heading: "Start with the state where work is governed", body: "Professional tax is administered through state-specific laws and official schedules rather than one national salary table. The employer's registered office may not answer which local rule applies to a worker who is posted elsewhere, works remotely, or changes location during a year. Check the relevant state department's portal, the establishment registration, the employee category, and the date of the schedule. The links below point to state portals for Maharashtra, Karnataka, West Bengal, Telangana, and Gujarat. They are navigation points, not a claim that one rate applies uniformly to every worker." },
      { heading: "Use the current schedule, not a search snippet", body: "State portals can publish an amended schedule, circular, notification, calculator, or payment interface in different places. Open the actual schedule and read its effective date before comparing a payslip. A press note or FAQ may explain a change without containing the complete rate table. If the portal has a tax-period selector, choose the period that matches the salary month. Do not rely on an old PDF indexed by a search engine when the department page lists a newer amendment. Save the document title, date, state, and the exact category row used." },
      { heading: "Match the employee category", body: "A schedule may distinguish salary earners, enrolled professionals, employers, traders, or other classes. A monthly deduction can depend on the wage band, place of work, enrollment status, exemption, or collection month. The employer's payroll method may also differ from a yearly total divided into equal months. Ask which entry and notification apply to your category and whether a special month or year-end adjustment is expected. If the payslip simply says PT, request the state, period, taxable category, and rate source. The abbreviation alone does not let you reconstruct the calculation." },
      { heading: "Review state changes and exemptions", body: "A transfer, remote-work arrangement, salary interruption, joining date, or exit date can affect how payroll handles a state deduction. Certain statutes provide exemptions or documentation routes, but eligibility must be checked against the current state law rather than inferred from age, salary, or job title. Ask payroll for the exemption rule and filing proof if no deduction appears. A zero line can reflect a lawful exemption, a missing registration, a timing issue, or a payroll error; it is not self-explanatory. Keep correspondence and the official portal receipt where the employer provides one." },
      { heading: "Illustrative scenario: office transfer mid-year", body: "Illustrative scenario: an employee moves from one state office to another while retaining the same employer. The employee records the effective work-location date, asks which payroll establishment will report the deduction, and checks both state portals for the schedule applicable to each period. The employee does not add two monthly amounts automatically or assume the prior state's rule continues. Payroll confirms whether a correction or exemption document is required. This is a reconciliation sequence, not tax advice and not a claim about the rates in either state." },
      { heading: "Five official portals, one careful workflow", body: "For Maharashtra, open the Profession Tax rate-schedule section of MAHAGST; for Karnataka, use the Commercial Taxes Department's Profession Tax notifications and linked Gazette material. West Bengal's Profession Tax portal and Commercial Taxes schedule provide state-specific notices; Telangana publishes a PT schedule through its Commercial Taxes Department; Gujarat's Commercial Tax site hosts its schedule page and rate documents. Portal paths may change, so use the department home navigation if a link moves. The source date in this library records when these official pages were opened, not a guarantee that no later amendment exists." },
      { heading: "Capture the evidence behind a deduction", body: "Keep the payslip month, work location, payroll employer, state registration, employee category, and schedule version in one record. If a deduction changes after a transfer, compare the effective date on the official notification with the first affected wage period. A department dashboard can help confirm registration or payment status, but it does not replace the statutory rate table. Where the employer pays an annual amount, ask how it allocated that charge across payroll months. Do not assume the amount deducted from a colleague applies to you when location, salary band, or enrollment status differs." },
      { heading: "When an official schedule is hard to locate", body: "Start at the department's own home page and follow the Profession Tax, Acts, Rules, Notifications, or Rate Schedule navigation. Check document metadata and publication dates; a search result may surface a superseded PDF above a current notice. If a state site requires a selection or script to display rates, record the selected profession and wage band and save the resulting official page or receipt. Ask payroll for the title and notification number it used. A payment portal can calculate a transaction, but the underlying statute and schedule remain the authority for whether that category and amount apply." }
    ],
    faqs: [
      { question: "Is there one professional-tax rate for India?", answer: "No. Check the official state schedule and the employee category that applies to the work period." },
      { question: "Can I use an old payslip as the current rate source?", answer: "Use the current government schedule for the relevant state and period; payroll history is only a comparison record." }
    ]
  },
  "/rules/hra-rent-exemption": {
    sections: [
      { heading: "Confirm the regime and tax year first", body: "House Rent Allowance treatment depends on the income-tax regime, the year, salary definition, accommodation, and evidence. This page explains the official formula for the regime and statute named in its source, not a universal benefit for everyone who pays rent. Check whether the current year still permits the exemption in your selected regime before estimating. A payroll declaration or rent receipt does not by itself prove eligibility. If the employee lives in an owned home, receives no HRA, or pays rent only for part of a year, the facts change the result." },
      { heading: "Understand the three-part comparison", body: "The Income Tax Department describes the exemption as the least of actual HRA received, rent paid minus ten percent of defined salary, and a location-based percentage of salary. The percentage depends on the specified metro classification; the salary base is not simply CTC or take-home cash. Compute each candidate amount separately, then compare the three values. Never subtract the full rent from taxable income as if it were the exemption. If rent less the salary threshold is negative, the allowable amount cannot become a positive exemption through arithmetic formatting." },
      { heading: "Build a month-by-month record", body: "Collect the employer's HRA statement, payslips, rent-payment evidence, occupancy dates, address, and landlord details required by the current process. If salary or rent changes during the year, divide the period into the relevant segments rather than applying one annual average to every month. Keep bank or UPI evidence where available and reconcile it with the rent receipt. A landlord's tax identifier or declaration should be shared only through the employer's secure process. Do not expose residential information in a public tool, analytics event, or unrelated application." },
      { heading: "Separate HRA from home-loan questions", body: "HRA exemption and a home-loan deduction are different tax provisions with separate conditions. Owning property does not automatically settle whether a rented residence qualifies, and paying a loan does not replace evidence of rent. A person can face a fact-specific interaction involving place of work, ownership, occupancy, family property, and statutory rules. Keep each claim on its own worksheet and avoid deducting the same payment twice. The tool should show the HRA arithmetic only; a tax professional or official return schedule can help determine whether the larger combination fits the taxpayer's circumstances." },
      { heading: "Illustrative scenario: a mid-year move", body: "Illustrative scenario: an employee rents a room near a new work location for part of a financial year, then moves to another city and receives a revised HRA amount. The employee divides the record at the move date, retains both rent agreements and payment trails, and applies the official formula to each eligible period. They check the city classification and salary definition from the current rule instead of labeling every large city a metro. The calculation helps organize evidence; it does not verify a landlord, establish occupancy, or guarantee that payroll accepts a claim." },
      { heading: "Avoid common record mismatches", body: "A rent agreement may name a family member while bank transfers come from another account; a receipt may cover dates outside the occupancy period; or a salary breakup may include a variable allowance that is not part of the formula's defined base. Explain any mismatch before submitting a declaration. Ask payroll which supporting records it requires and keep the answer. If the employee works from a different city than the rented home or has multiple employers, ask how each period should be reported. Correcting a fact is safer than altering a number to make the computed exemption appear plausible." },
      { heading: "Document the formula inputs", body: "Write down actual HRA, eligible salary for the chosen period, rent paid, city classification, and the three candidate amounts before selecting the minimum. For a salary revision or city move, create separate rows for the before-and-after periods. Retain agreement dates, receipts, transfer confirmations, and employer declarations in a restricted folder. If the landlord is a relative or a shared household pays the rent, explain the arrangement and verify the current documentary requirement instead of silently splitting the payment. The worksheet should expose each input so an auditor or payroll reviewer can reproduce the result." },
      { heading: "Check partial-year employment", body: "A new job, unpaid leave, or mid-year relocation may leave only a portion of the year eligible for an HRA comparison. Use the dates on the lease and payroll record rather than multiplying a monthly estimate by twelve automatically. If two employers paid HRA during the same financial year, collect both statements and confirm how the return handles the combined salary. Track any rent-free days or employer-provided housing separately. An annualised estimate can be useful for planning, but the filed computation should reflect actual received allowance, rent, and salary for each relevant period." }
    ],
    faqs: [
      { question: "Can I claim the full rent as exempt?", answer: "No. The official method compares three amounts and permits the least, subject to eligibility." },
      { question: "Does this page decide whether I qualify?", answer: "No. It explains arithmetic; occupancy, regime, salary definition, and evidence still matter." }
    ]
  },
  "/rules/ctc-components": {
    sections: [
      { heading: "Treat CTC as an employer's package label", body: "Cost to company is commonly used in offer and payroll communication, but the label alone does not tell an employee what reaches a bank account, what is conditional, or what is a tax valuation. Ask for the component schedule and the document that governs each item. Fixed cash, variable incentive, employer retirement contribution, insurance premium, gratuity provision, and equity may be displayed together while following different timing and eligibility rules. A package total can be useful for comparing employer cost only after the components are separated. Do not call its full annual number monthly take-home pay." },
      { heading: "Separate cash, conditional pay, and benefits", body: "Fixed salary is different from a target incentive whose payout depends on a plan. Reimbursements may require proof and can have different tax treatment from a flat allowance. Employer-paid insurance creates coverage rather than cash in hand; retirement contributions may vest, post, or become accessible under distinct conditions. Stock awards can have grant, vesting, exercise, and sale stages. For every line, ask amount, period, trigger, payroll treatment, and whether it is included in the headline total. The word guaranteed should appear only where the signed terms support it." },
      { heading: "Read the offer documents together", body: "Compare the offer letter with annexures, incentive plan, benefits policy, joining-bonus clause, location letter, and any later amendment. Check whether the package states annual target or maximum, whether partial-year service is prorated, and whether the employer may revise components. Ask about notice recovery, repayment deadlines, probation, joining date, and the treatment of unpaid leave. A recruiter email can clarify intent but may not amend a signed contract. Keep the latest dated version of every document and ask an authorized HR contact to confirm material differences in writing." },
      { heading: "Illustrative scenario: two offers with different mixes", body: "Illustrative scenario: one employer offers a larger headline CTC with a modest fixed portion and a variable award; another presents a smaller total with more fixed cash and a separate insurance benefit. The candidate writes down each component's payment date, conditions, tax treatment, and expected net cash before comparing. They do not count insurance as spendable income or assume the target award will pay in full. They also ask about probation and clawback clauses. This comparison is more informative than sorting the two offers by headline value alone." },
      { heading: "Reconcile the package with tax records", body: "The Income-tax Act classifies salary, perquisites, and profits in lieu of salary; the employer's CTC presentation does not override those classifications. Compare payslips and the salary certificate (Form 16, or Form 130 from tax year 2026–27) with the offer schedule to identify taxable allowances, benefits, retirement-fund contributions, and withholding. A benefit can be taxable without being a cash payment, and a CTC line can be an employer cost that is not currently taxable to the employee. Use the official salary guide for current treatment and ask payroll how it valued each item. Do not transfer a package total into a tax field without reading its components." },
      { heading: "Build an apples-to-apples comparison", body: "Put both offers on the same time horizon, currency, location, and employment start date. Show first-year cash separately from recurring annual cash and from long-term or conditional value. Add relocation, commute, insurance gaps, and joining-bonus repayment only when a document supports the cost. If an offer is incomplete, mark the blank term as unknown instead of inventing a value. A written comparison can include non-financial trade-offs such as scope, manager access, schedule, or caregiving fit, but those are personal judgements rather than official tax facts. The purpose is clearer choice, not a universal employer ranking." },
      { heading: "Check vesting, forfeiture, and recovery language", body: "For stock awards, note the grant date, vesting schedule, exercise price, lock-up, sale window, and what happens when employment ends. For a joining incentive, record whether repayment is gross or net, the period covered, any pro-rata reduction, and the event that triggers recovery. For a variable plan, check eligibility dates, target versus cap, performance conditions, and when management may change the award. These terms can dominate first-year value even when the package table looks simple. Ask HR to identify the controlling document for each promise and keep a signed copy rather than relying on a recruitment slide." },
      { heading: "Audit the monthly payslip against the annual package", body: "After joining, reconcile each month's fixed earnings, variable payout, statutory deductions, employer contributions, and benefit valuations with the offer schedule. Identify amounts that are quarterly, annual, or paid only after a performance review so they are not mistaken for missing monthly salary. Compare the gross earnings total with taxable salary rather than assuming the two columns match. Ask payroll to explain unexplained codes before year-end; correcting a classification early is easier than reconstructing it when a tax certificate is due. Keep a personal note of changes to the package and the date each amendment took effect." }
    ],
    faqs: [
      { question: "Is CTC the same as take-home pay?", answer: "No. It can include conditional pay and employer costs that do not arrive as monthly cash." },
      { question: "Can I trust a verbal package promise?", answer: "Ask for the component, condition, and payment timing in the controlling written documents." }
    ]
  },
  "/rules/salary-benefits-tax": {
    sections: [
      { heading: "Identify the employer–employee relationship", body: "The official salary guide distinguishes income from employment from payments made in other relationships. A consultant, partner, director, agent, or contractor may receive money from the same organisation without every payment being salary under the same provision. Before classifying an amount, check who paid it, why it was paid, the contractual relationship, and the period it relates to. A payroll label can assist but does not replace the statutory definition. When the relationship is disputed, preserve the agreement and seek advice rather than selecting the more convenient tax head." },
      { heading: "Inspect allowances and reimbursements", body: "An allowance is not automatically exempt because it has a familiar name, and a reimbursement is not automatically tax-free because the employee submitted a bill. Review the statutory provision, the purpose of the payment, the documentation, the employer's policy, and the return schedule for the relevant year. Record whether the amount is paid as a fixed monthly sum, repaid against actual expense, or limited to a qualifying use. If a payroll code says travel, food, phone, or special allowance, ask for the classification and valuation rule. Similar labels can conceal different legal treatment." },
      { heading: "Value benefits using the governing rule", body: "Company accommodation, vehicles, concessional services, stock awards, insurance, and employer retirement contributions may have their own valuation methods and timing. The taxable amount need not equal the employer's procurement cost or the value shown in a CTC summary. Ask payroll for the underlying calculation, valuation date, employee contribution, and any relevant cap. Where shares are involved, separate grant, vesting, exercise, and eventual sale records because those events may have separate tax consequences. Keep the official rule used for the year instead of relying on a prior colleague's example." },
      { heading: "Compare the salary certificate with source records", body: "Collect monthly payslips, annual salary statements, reimbursement approvals, benefit statements, prior-employer salary details, and tax-declaration confirmations. Trace each amount on the certificate (Form 16 for salary paid up to March 2026, Form 130 from April 2026) to one or more records and note when the employer corrected a figure. Check that income from a previous job was reported to the current payroll where required. If a benefit appears on a portal but not in the annual statement, ask whether it was omitted, valued in another period, or reported elsewhere. An itemized query is easier to resolve than a broad complaint that the tax total looks wrong." },
      { heading: "Illustrative scenario: a reimbursed work device", body: "Illustrative scenario: an employee buys a device after manager approval and later receives a repayment. The employee keeps the invoice, approval, proof of payment, device-ownership terms, and payroll code. They ask whether the employer treated the payment as reimbursement, allowance, or a benefit, and which rule determined the salary certificate entry. The employee does not assume the treatment from the word reimbursement alone. This example is a records checklist; it does not decide how a particular device or policy is taxed." },
      { heading: "Keep personal records private", body: "Tax documents contain identity, salary, address, and financial information. Store copies in a private location, redact account identifiers before sharing, and use the employer's secure payroll channel for questions. This website does not ask users to upload a payslip or tax return to answer a rules question. If you need professional help, share only the records necessary for the adviser to assess the issue. A public educational summary should not become a place where sensitive documents, tax identifiers, or payroll account details are copied for convenience." },
      { heading: "Resolve a classification mismatch deliberately", body: "When the salary certificate (Form 16 or Form 130), the payslip, and the offer schedule disagree, list the exact amount, period, and record on each side before contacting payroll. Ask whether the variance comes from valuation, a late declaration, a previous employer, a benefit event, or an amended statement. Request a corrected document if the employer confirms an error, then reconcile the withholding already remitted. Do not edit a filed return merely to match a draft salary slip. Keep the response with the source record and note which version of the official guidance supported the final classification." },
      { heading: "Write a clean question for payroll", body: "Include the payment date, gross amount, payroll code, agreement clause, and annual statement line that appear inconsistent. Ask the employer to name the provision or valuation rule and whether it has reported the same amount on the salary certificate. A focused request is more likely to produce an answer that can be checked than a message asking whether the tax is correct in general. Avoid attaching a full bank export or identity document when a redacted payslip excerpt is sufficient. Store the reply with the affected record and mark whether it changed withholding, taxable income, or only the wording on the certificate." }
    ],
    faqs: [
      { question: "Does every employer payment count as salary?", answer: "Classification depends on the relationship, purpose, contract, and applicable statutory rule." },
      { question: "Does CTC determine a taxable benefit's value?", answer: "Not necessarily. Use the valuation method and timing prescribed for the benefit." }
    ]
  }
};
